    </div>
    <div class="kpi-card">
      <h3>Reporting Coverage (2023)</h3>
      <div class="value">''' + str(round([c for c in data['coverage'] if c['year']==2023][0]['coverage_rate'],1)) + '''%</div>
      <div class="sub">''' + str(data['stats']['countries_2023']) + ''' of ''' + str(data['stats']['total_countries']) + ''' countries</div>
    </div>
