// Sex global medians
new Chart(document.getElementById('chartSexGlobal'), {
  type: 'line',
  data: {
    labels: sexYearly.map(d => d.year),
    datasets: [
      { label: 'Male Median', data: sexYearly.map(d => d.median_male), borderColor: '#2563eb', backgroundColor: 'transparent', tension: 0.3, pointRadius: 2 },
      { label: 'Female Median', data: sexYearly.map(d => d.median_female), borderColor: '#db2777', backgroundColor: 'transparent', tension: 0.3, pointRadius: 2 }
